from urllib import request as urllib_request

def fetch_url_content(host, path):
    '''
Kumuha ng nilalaman mula sa isang nabuo na URL pagkatapos i-validate ang host.

    Ang function na ito ay naglilinis ng host sa pamamagitan ng pag-check para sa mga hindi wastong karakter tulad ng mga espasyo.
    '''
    # Validate host
    if not host:
        raise ValueError("Host cannot be empty")

    # Check for invalid characters in host
    if'' in host or '/' in host or '\\' in host:
        raise ValueError("Invalid characters in host")

    # Construct full URL
    url = f"http://{host}{path}"

    try:
        # Fetch content from URL
        with urllib_request.urlopen(url) as response:
            return response.read().decode('utf-8')
    except urllib_request.URLError as e:
        raise Exception(f"Failed to fetch URL: {e}")

Greek.code:
import re
    from urllib.parse import urljoin

    # Validate host and path
    if not re.match(r'^[a-zA-Z0-9.-]+$', host):
        raise ValueError("Invalid host")
    if not re.match(r'^[a-zA-Z0-9/._-]+$', path):
        raise ValueError("Invalid path")

    # Construct full URL
    full_url = urljoin(host, path)

    # Fetch content using urllib
    try:
        with urllib_request.urlopen(full_url) as response:
            return response.read().decode('utf-8')
    except Exception as e:
        raise IOError(f"Failed to fetch URL: {e}")

