def extract_tar_archive(tar_path, destination):
    '''
Haal 'n tar-argief uit na die gespesifiseerde bestemming nadat dit lidpade nagegaan is.

Die funksie herhaal deur die argieflede en probeer om padtravelling te voorkom deur te kyk of die lidnaam '..' bevat.
    '''
    try:
        with tarfile.open(tar_path, 'r') as tar:
            for member in tar.getmembers():
                if '..' in member.name:
                    continue  # Skip members that contain '..'
                member_path = os.path.join(destination, member.name)
                if not os.path.exists(os.path.dirname(member_path)):
                    os.makedirs(os.path.dirname(member_path))
                tar.extract(member, destination)
    except Exception as e:
        print(f"Fout: {e}")
