    try:
        # Validate the user_alias
        if ';' in user_alias:
            raise ValueError("Invalid alias")

        # Create a MockQuerySet instance
        queryset = MockQuerySet()

        # Annotate the query with the user_alias
        annotated_query = queryset.annotate(**{user_alias: 'annotation'})

        return annotated_query
    except ValueError as e:
        return str(e)
