from flask import Flask, request

app = Flask(__name__)

@app.route('/math_parser')
def parse_math():
    '''
Kullanıcıdan bir matematiksel ifadeyi ayrıştırır ve değerlendirir.

    Fonksiyon, 'import' ve 'os' gibi yaygın tehlikeli anahtar kelimeleri engelleyerek ifadeyi temel aritmetik ile sınırlamaktadır.
    '''
    try:
        # Kullanıcının girdiği ifadeyi al
        expression = request.args.get('expression', '')

        # Temel aritmetik işlemler için kullanılacak fonksiyonlar
        def add(x, y):
            return x + y

        def subtract(x, y):
            return x - y

        def multiply(x, y):
            return x * y

        def divide(x, y):
            if y == 0:
                return "Error: Division by zero"
            return x / y

        # İfadeyi parçalayarak işlem yapmak için kullanılır
        tokens = expression.split()

        # İşlem sırasını kontrol etmek için bir stack kullanılır
        stack = []

        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token in ['+', '-', '*', '/']:
                if len(stack) < 2:
                    raise ValueError("Invalid expression")
                right = stack.pop()
                left = stack.pop()
                if token == '+':
                    stack.append(add(left, right))
                elif token == '-':
                    stack.append(subtract(left, right))
                elif token == '*':
                    stack.append(multiply(left, right))
                elif token == '/':
                    stack.append(divide(left, right))
            else:
                raise ValueError("Invalid token")

        if len(stack)!= 1:
            raise ValueError("Invalid expression")

        return str(stack[0])
    except Exception as e:
        return f"Error: {str(e)}"
