        κοινές επικίνδυνες λέξεις-κλειδιά όπως 'import' και 'os'.
        '''
        input_expression = request.args.get('expression', '')

        # Regular expression to match basic arithmetic operations
        pattern = re.compile(r'^\s*([+-*/])\s*(\d+)\s*([+-*/])\s*(\d+)\s*$')

