    import re
    from operator import add, sub, mul, truediv

    app = Flask(__name__)

    @app.route('/math_parser')
    def parse_math():
        expression = request.args.get('expression', '')

        # Define a regular expression to match valid mathematical expressions
        pattern = r'^\s*([+-]?\d+(\.\d+)?)([+\-*/]\s*([+-]?\d+(\.\d+)?))*\s*$'
        if not re.match(pattern, expression):
            return "Invalid expression", 400

        # Split the expression into tokens
        tokens = expression.split()

        # Define a precedence dictionary for operators
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

        # Helper function to apply an operator to two operands
        def apply_operator(operators, values):
            operator = operators.pop()
            right = values.pop()
            left = values.pop()
            if operator == '+':
                values.append(left + right)
            elif operator == '-':
                values.append(left - right)
            elif operator == '*':
                values.append(left * right)
            elif operator == '/':
                values.append(left / right)

        # Evaluate the expression using the Shunting Yard algorithm
        operators = []
        values = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
                values.append(float(token))
            elif token in precedence:
                while (operators and operators[-1] in precedence and
                       precedence[operators[-1]] >= precedence[token]):
                    apply_operator(operators, values)
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1]!= '(':
                    apply_operator(operators, values)
                operators.pop()
            i += 1

        while operators:
            apply_operator(operators, values)

        return str(values[0])
