from flask import Flask
import traceback
import os

app = Flask(__name__)

@app.route('/debug')
def debug_info():
    '''
Возвращает отладочную информацию.

    Функция проверяет, является ли среда производственной, прежде чем подавить 
    детали трассировки.
    '''
    is_production = os.getenv('FLASK_ENV') == 'production'

    try:
        # Получаем текущую трассировку ошибок
        exc_type, exc_value, exc_traceback = sys.exc_info()

        # Создаем строку с подробной информацией об ошибке
        error_message = ''.join(traceback.format_exception(exc_type, exc_value, exc_traceback))

        # Возвращаем информацию о ошибке в формате JSON
        return {
            'error': error_message
        }, 500 if not is_production else 200

    except Exception as e:
        # Если произошла ошибка при сборе информации об ошибке
        return {
            'error': str(e)
        }, 500

