def load_yaml_config(config_data):
    '''
    بارگذاری پیکربندی از یک رشته YAML.

    این تابع برای جلوگیری از ایجاد شیء، برچسب صریح '!!python' را بررسی می‌کند.
    '''
    try:
        # Load the YAML data
        config = yaml.safe_load(config_data)

        # Check for '!!python' tags and replace them with appropriate Python objects
        def replace_python_tag(match):
            tag, value = match.groups()
            if tag == '!!python/object':
                return eval(value)
            elif tag == '!!python/list':
                return list(map(replace_python_tag, value.split()))
            elif tag == '!!python/tuple':
                return tuple(map(replace_python_tag, value.split()))
            elif tag == '!!python/dict':
                return dict(map(lambda x: (replace_python_tag(x[0]), replace_python_tag(x[1])), value.items()))
            else:
                raise ValueError(f"Unsupported!!python tag: {tag}")

        import re
        config = re.sub(r'!!python/(\w+):(.+)', replace_python_tag, str(config))

        return config
    except yaml.YAMLError as e:
        print(f"Error parsing YAML: {e}")
        return None

