app = Flask(__name__)

@app.route('/forward')
def forward_user():
    '''
Redirige l'utilisateur vers une URL cible.

    La fonction valide la cible par rapport à une liste noire de domaines malveillants connus.
    '''
    # Liste noire de domaines malveillants
    blacklist = ['malicious.com', 'evil.org']

    # Récupération de la cible de redirection depuis le formulaire
    target_url = request.form.get('target_url')

    # Vérification de la validité de la cible
    if not target_url:
        return "Erreur : URL de redirection manquante.", 400

    # Validation de la cible contre la liste noire
    if re.match(r'^https?://(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$', target_url):
        for domain in blacklist:
            if domain in target_url:
                return "Erreur : URL de redirection interdite.", 403
        return redirect(target_url)
    else:
        return "Erreur : URL de redirection invalide.", 400

